// Copies the notification wording and de-duplication rules (packages/shared/src/push) into the Edge Function folder as one
// plain JavaScript file, so the server sends exactly what the apps and tests expect. Run: npm run push:build
// (A test fails if the generated file is out of date.)
import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const HEADER = "// GENERATED by `npm run push:build` from packages/shared/src/push. Do not edit by hand.\n";

export async function generate() {
  const out = await build({
    entryPoints: [resolve(root, "packages/shared/src/push/index.ts")],
    bundle: true, format: "esm", platform: "neutral", target: "es2022", write: false, logLevel: "error", absWorkingDir: root,
  });
  return HEADER + out.outputFiles[0].text;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const defaultTarget = resolve(root, "supabase/proposals/functions/notify-push/shared-push.js");
  // `--check [file]` compares a file (default: the real one) with a fresh build and exits 1 when they differ.
  const checkIndex = process.argv.indexOf("--check");
  const target = checkIndex !== -1 && process.argv[checkIndex + 1] ? resolve(process.argv[checkIndex + 1]) : defaultTarget;
  const fresh = await generate();
  if (checkIndex !== -1) {
    const current = await readFile(target, "utf8").catch(() => "");
    if (current !== fresh) { console.error("shared-push.js is out of date. Run: npm run push:build"); process.exit(1); }
    console.log("shared-push.js is up to date");
  } else {
    await writeFile(target, fresh, "utf8");
    console.log("Wrote", target);
  }
}
